210	    /**
211	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
212	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
213	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
214	     * (so the field is absent from the response) or the registration date is unknown.
215	     */
216	    public String getAgeBand() {
217	        if (this.birthDate == null || this.registrationDate == null) {
218	            return null;
219	        }
220	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
221	        if (age < 18) {
222	            return "MINOR";
223	        }
224	        if (age < 65) {
225	            return "ADULT";
226	        }
227	        return "SENIOR";
228	    }
