262	    /**
263	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
264	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
265	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
266	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
267	     * count is recomputed on each read because household membership changes as owners come and go.
268	     */
269	    public void setHouseholdSize(Integer householdSize) {
270	        this.householdSize = householdSize;
271	    }
