273	    /**
274	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
275	     * have already been created for this owner's registration day. Computed per request, not persisted.
276	     */
277	    public Boolean getBulkSignupWarning() {
278	        return this.bulkSignupWarning;
279	    }
