285	    /**
286	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
287	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
288	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
289	     * {@code sharesHousehold}), which is not a suspected duplicate.
290	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
291	     */
292	    public Boolean getPossibleDuplicate() {
293	        return this.possibleDuplicate;
294	    }
295	
296	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
297	        this.possibleDuplicate = possibleDuplicate;
298	    }
299	
300	    /**
301	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
302	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
303	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
304	     */
305	    public Integer getPossibleDuplicateOf() {
306	        return this.possibleDuplicateOf;
307	    }
308	
309	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
310	        this.possibleDuplicateOf = possibleDuplicateOf;
311	    }
312	
313	    /**
314	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
315	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
316	     * {@link #setHouseholdSize(Integer)}); add 3 for tenure of more than 365 days (measured from
317	     * {@code registrationDate} to today). A newly created owner has zero tenure, so a fresh owner scores
318	     * at most 5 points (2 + 1 + 2).
319	     */
320	    public int getMembershipPoints() {
321	        int points = 0;
322	        boolean hasEmail = this.email != null && !this.email.isBlank();
323	        if (hasEmail) {
324	            points += 2;
325	        }
326	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
327	        if (unique) {
328	            points += 1;
329	        }
330	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
331	        if (largeHousehold) {
332	            points += 2;
333	        }
334	        boolean tenured = this.registrationDate != null
335	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
336	        if (tenured) {
337	            points += 3;
338	        }
339	        return points;
340	    }
341	
342	    /**
343	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
344	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
345	     */
346	    public int getMembershipLevel() {
347	        int points = getMembershipPoints();
348	        if (points <= 1) {
349	            return 1;
350	        }
351	        if (points <= 3) {
352	            return 2;
353	        }
354	        if (points <= 5) {
355	            return 3;
356	        }
357	        return 4;
358	    }
