1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.HouseholdDuplicateException;
8	
9	/**
10	 * The single duplicate check for a new owner, keyed on the household. Because the {@code householdId} is
11	 * now deterministic from the (lastName, postcode) pair (see {@link Household}), two owners that share a
12	 * last name and postcode are the same household. A new owner whose computed household id already belongs
13	 * to an existing owner is therefore rejected with a 409 Conflict ({@link HouseholdDuplicateException}).
14	 *
15	 * <p>The {@code sharesHousehold} request flag bypasses this block: when set, the owner is admitted as a
16	 * declared member of the household rather than rejected (it is then not treated as a suspected duplicate
17	 * — see {@link FlagPossibleDuplicate}). The flag only lifts the block; it does not affect the derived
18	 * {@code householdId}, which is assigned deterministically by {@link AssignHousehold}.
19	 *
20	 * <p>Runs after {@link ValidateNewOwner} and {@link ValidateOwnerPostcode} (so the last name is present
21	 * and the postcode has been validated) and before {@link BuildOwner}. Existing owners are compared by
22	 * their household id recomputed from their own last name and postcode, so seed data whose
23	 * {@code householdId} was never assigned still collides with an equivalent request.
24	 */
25	public class CheckHouseholdUnique {
26	
27	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws HouseholdDuplicateException {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return; // declared household member: bypass the duplicate block
31	        }
32	        String householdId = Household.id(request.getLastName(), request.getPostcode());
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (householdId.equals(Household.id(existing.getLastName(), existing.getPostcode()))) {
35	                throw new HouseholdDuplicateException(householdId);
36	            }
37	        }
38	    }
39	}
