2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single source of truth for household identity. A household groups owners that share the same last
10	 * name and the same postcode, with the last name compared case-insensitively and with surrounding and
11	 * internal whitespace collapsed (so "Smith" / " smith " belong together).
12	 *
13	 * <p>The {@link #id(String, String)} derived from that normalized (lastName, postcode) pair is
14	 * deterministic: the same last name and postcode always map to the same value, so every owner at the
15	 * same household receives an identical {@code householdId} automatically — it is no longer something an
16	 * owner "joins" via {@code sharesHousehold}. The household is therefore the basis for duplicate
17	 * detection ({@link CheckHouseholdUnique}): two owners belong to the same household exactly when their
18	 * ids are equal.
19	 */
20	final class Household {
21	
22	    private Household() {
23	    }
24	
25	    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
26	    private static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
31	    }
32	
33	    /**
34	     * The canonical household key for a (lastName, postcode) pair — the single definition of household
35	     * membership: {@code normalizedLastName + "|" + postcode}. Two owners belong to the same household
36	     * exactly when their keys are equal; {@link #id} hashes this same key, so the duplicate check and the
37	     * assigned id can never diverge. The last name is normalized (whitespace collapsed, lower-cased); the
38	     * postcode is trimmed and used as given (a {@code null} or blank postcode contributes an empty
39	     * component).
40	     */
41	    static String key(String lastName, String postcode) {
42	        String pc = (postcode == null) ? "" : postcode.trim();
43	        return normalize(lastName) + "|" + pc;
44	    }
45	
46	    /**
47	     * Deterministic household identifier for the given last name and postcode: {@code "H-"} followed by
48	     * the first 12 hex characters of the SHA-256 of the {@link #key household key}.
49	     */
50	    static String id(String lastName, String postcode) {
51	        String key = key(lastName, postcode);
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
54	            StringBuilder sb = new StringBuilder("H-");
55	            for (int i = 0; i < 6; i++) {
56	                sb.append(String.format("%02x", digest[i]));
57	            }
58	            return sb.toString();
59	        }
60	        catch (NoSuchAlgorithmException e) {
61	            throw new IllegalStateException("SHA-256 not available", e);
62	        }
63	    }
64	}
