203	        return this.birthDate;
204	    }
205	
206	    public void setBirthDate(LocalDate birthDate) {
207	        this.birthDate = birthDate;
208	    }
209	
210	    /**
211	     * The owner's age band, derived from {@link #getBirthDate() birthDate} measured against the
212	     * {@link #getRegistrationDate() registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
213	     * when 18 to 64, or {@code "SENIOR"} when 65 or older. {@code null} when no birth date is present
214	     * (so the field is absent from the response) or the registration date is unknown.
215	     */
216	    public String getAgeBand() {
217	        if (this.birthDate == null || this.registrationDate == null) {
218	            return null;
219	        }
220	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
221	        if (age < 18) {
222	            return "MINOR";
223	        }
224	        if (age < 65) {
225	            return "ADULT";
226	        }
227	        return "SENIOR";
228	    }
229	
230	    public String getCustomerCode() {
231	        return this.customerCode;
232	    }
233	
234	    public void setCustomerCode(String customerCode) {
235	        this.customerCode = customerCode;
236	    }
237	
238	    public String getMembershipNumber() {
239	        return this.membershipNumber;
240	    }
241	
242	    public void setMembershipNumber(String membershipNumber) {
243	        this.membershipNumber = membershipNumber;
244	    }
245	
246	    public String getHouseholdId() {
247	        return this.householdId;
248	    }
249	
250	    public void setHouseholdId(String householdId) {
251	        this.householdId = householdId;
252	    }
253	
254	    public Integer getNamesakeCount() {
255	        return this.namesakeCount;
256	    }
257	
258	    public void setNamesakeCount(Integer namesakeCount) {
259	        this.namesakeCount = namesakeCount;
260	    }
261	
262	    /**
263	     * Sets the number of owners that belong to this owner's household (same last name and postcode; see
264	     * {@link org.springframework.samples.petclinic.rest.function.owner.Household}), including this owner.
265	     * Computed per request and used only by {@link #getMembershipPoints()} — a household of three or more
266	     * contributes points. Not persisted and not serialized into the response (no getter is exposed); the
267	     * count is recomputed on each read because household membership changes as owners come and go.
268	     */
269	    public void setHouseholdSize(Integer householdSize) {
270	        this.householdSize = householdSize;
271	    }
272	
273	    /**
274	     * Whether this response should carry a bulk-signup warning: {@code true} when more than 80 owners
275	     * have already been created for this owner's registration day. Computed per request, not persisted.
276	     */
277	    public Boolean getBulkSignupWarning() {
278	        return this.bulkSignupWarning;
279	    }
280	
281	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
282	        this.bulkSignupWarning = bulkSignupWarning;
283	    }
284	
285	    /**
286	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
287	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
288	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
289	     * {@code sharesHousehold}), which is not a suspected duplicate.
290	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
291	     */
292	    public Boolean getPossibleDuplicate() {
293	        return this.possibleDuplicate;
294	    }
295	
296	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
297	        this.possibleDuplicate = possibleDuplicate;
298	    }
299	
300	    /**
301	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
302	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
303	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
304	     */
305	    public Integer getPossibleDuplicateOf() {
306	        return this.possibleDuplicateOf;
307	    }
308	
309	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
310	        this.possibleDuplicateOf = possibleDuplicateOf;
311	    }
