313	    /**
314	     * The owner's membership points: start at 0; add 2 when an email is present; add 1 when
315	     * {@code namesakeCount} is 0; add 2 for a household of 3 or more members (see
316	     * {@link #setHouseholdSize(Integer)}); add 3 for tenure of more than 365 days (measured from
317	     * {@code registrationDate} to today). A newly created owner has zero tenure, so a fresh owner scores
318	     * at most 5 points (2 + 1 + 2).
319	     */
320	    public int getMembershipPoints() {
321	        int points = 0;
322	        boolean hasEmail = this.email != null && !this.email.isBlank();
323	        if (hasEmail) {
324	            points += 2;
325	        }
326	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
327	        if (unique) {
328	            points += 1;
329	        }
330	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
331	        if (largeHousehold) {
332	            points += 2;
333	        }
334	        boolean tenured = this.registrationDate != null
335	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
336	        if (tenured) {
337	            points += 3;
338	        }
339	        return points;
340	    }
341	
342	    /**
343	     * The owner's membership level, derived from {@link #getMembershipPoints() membershipPoints}:
344	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
345	     */
346	    public int getMembershipLevel() {
347	        int points = getMembershipPoints();
348	        if (points <= 1) {
349	            return 1;
350	        }
351	        if (points <= 3) {
352	            return 2;
353	        }
354	        if (points <= 5) {
355	            return 3;
356	        }
357	        return 4;
358	    }
359	
360	    /**
361	     * Fixed city-to-region table mapping each known city to its canonical region string.
362	     */
363	    private static final Map<String, String> CITY_REGION = Map.of(
364	        "Sydney", "NSW",
365	        "Melbourne", "VIC",
366	        "Brisbane", "QLD");
367	
368	    /**
369	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
370	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
371	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
372	     */
373	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
374	        "NSW", new int[] {2000, 2099},
375	        "VIC", new int[] {3000, 3099},
376	        "QLD", new int[] {4000, 4099});
377	
378	    /**
379	     * Fixed region-to-timezone table mapping each known region to its IANA timezone name
380	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). The single
381	     * source of truth for the timezone derivation read by {@link #getTimezone()}.
382	     */
383	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
384	        "NSW", "Australia/Sydney",
385	        "VIC", "Australia/Melbourne",
386	        "QLD", "Australia/Brisbane");
387	
388	    /**
389	     * The canonical region for {@code city} derived from the fixed city-to-region table
390	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
391	     * city is not in the table. The single source of truth for the create-time postcode range check in
392	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
393	     */
394	    public static String regionOf(String city) {
395	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
396	    }
397	
398	    /**
399	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
400	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
401	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
402	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
403	     * postcode range check.
404	     */
405	    public static int[] postcodeRangeOf(String region) {
406	        return REGION_POSTCODES.get(region);
407	    }
408	
409	    /**
410	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
411	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
412	     * range.
413	     */
414	    public static String regionOfPostcode(String postcode) {
415	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
416	            return null;
417	        }
418	        int value = Integer.parseInt(postcode);
419	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
420	            int[] range = entry.getValue();
421	            if (value >= range[0] && value <= range[1]) {
422	                return entry.getKey();
423	            }
424	        }
425	        return null;
426	    }
427	
428	    /**
429	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
430	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
431	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
432	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
433	     * customer code is assigned.
434	     */
435	    public String getLocality() {
436	        if (this.customerCode == null) {
437	            return "UNKNOWN";
438	        }
439	        int dash = this.customerCode.indexOf('-');
440	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
441	    }
442	
443	    /**
444	     * The owner's IANA timezone, derived from the {@link #getLocality() locality}/region via the fixed
445	     * region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
446	     * QLD -> Australia/Brisbane), or {@code null} (so the field is absent from the response) when the
447	     * locality maps to no known region.
448	     */
449	    public String getTimezone() {
450	        return REGION_TIMEZONE.get(getLocality());
451	    }
452	
453	    /**
454	     * The single Luhn check digit (0-9) computed over the digits contained in the
455	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
456	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
457	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
458	     */
459	    public int getCheckDigit() {
460	        String code = this.customerCode;
461	        if (code == null) {
462	            return 0;
463	        }
464	        int sum = 0;
465	        boolean dbl = true;
466	        for (int i = code.length() - 1; i >= 0; i--) {
467	            char c = code.charAt(i);
468	            if (c < '0' || c > '9') {
469	                continue;
470	            }
471	            int d = c - '0';
472	            if (dbl) {
473	                d *= 2;
474	                if (d > 9) {
475	                    d -= 9;
476	                }
477	            }
478	            sum += d;
479	            dbl = !dbl;
480	        }
481	        return (10 - (sum % 10)) % 10;
482	    }
483	
484	    /**
485	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
486	     * {@code "PHONE"}.
487	     */
488	    public String getContactPreference() {
489	        boolean hasEmail = this.email != null && !this.email.isBlank();
490	        return hasEmail ? "EMAIL" : "PHONE";
491	    }
492	
493	    /**
494	     * The single canonical format of an owner's derived identity key:
495	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
496	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
497	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
498	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
499	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
500	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
501	     * {@code CheckHouseholdUnique}).
502	     */
503	    public static String identityKey(String telephone, String email, String householdId) {
504	        String tel = (telephone == null) ? "" : telephone;
505	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
506	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
507	        return tel + "|" + mail + "|" + household;
508	    }
509	
510	    /**
511	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
512	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
513	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
514	     */
515	    public String getIdentityKey() {
516	        return identityKey(this.telephone, this.email, this.householdId);
517	    }
518	
519	    protected Set<Pet> getPetsInternal() {
520	        if (this.pets == null) {
521	            this.pets = new HashSet<>();
522	        }
523	        return this.pets;
524	    }
525	
526	    protected void setPetsInternal(Set<Pet> pets) {
527	        this.pets = pets;
528	    }
529	
530	    public List<Pet> getPets() {
531	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
532	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
533	        return Collections.unmodifiableList(sortedPets);
534	    }
535	
536	    public void setPets(List<Pet> pets) {
537	        this.pets = new HashSet<>(pets);
538	    }
539	
540	    public void addPet(Pet pet) {
541	        getPetsInternal().add(pet);
542	        pet.setOwner(this);
543	    }
544	
545	    /**
546	     * Return the Pet with the given name, or null if none found for this Owner.
547	     *
548	     * @param name to test
549	     * @return true if pet name is already in use
550	     */
551	    public Pet getPet(String name) {
552	        return getPet(name, false);
553	    }
554	
555	    /**
556	     * Return the Pet with the given name, or null if none found for this Owner.
557	     *
558	     * @param name to test
559	     * @return true if pet name is already in use
560	     */
561	    public Pet getPet(String name, boolean ignoreNew) {
562	        name = name.toLowerCase();
563	        for (Pet pet : getPetsInternal()) {
564	            if (!ignoreNew || !pet.isNew()) {
565	                String compName = pet.getName();
566	                compName = compName.toLowerCase();
567	                if (compName.equals(name)) {
568	                    return pet;
569	                }
570	            }
571	        }
572	        return null;
573	    }
574	
575	    public Pet getPet(Integer petId) {
576	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
577	    }
578	
579	    @Override
580	    public String toString() {
581	        return new ToStringCreator(this)
582	
583	            .append("id", this.getId())
584	            .append("new", this.isNew())
585	            .append("lastName", this.getLastName())
586	            .append("firstName", this.getFirstName())
587	            .append("address", this.address)
588	            .append("city", this.city)
589	            .append("telephone", this.telephone)
590	            .toString();
591	    }
592	}
